package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {



    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Simple hex should be true", NumberUtils.isNumber("0x123"));
        assertTrue("Hex with uppercase should be true", NumberUtils.isNumber("0xABC"));
        assertTrue("Hex with mixed case should be true", NumberUtils.isNumber("0x1a2B"));
        assertFalse("Hex '0x' alone should be false", NumberUtils.isNumber("0x"));
        assertFalse("Hex with invalid char should be false", NumberUtils.isNumber("0x12G"));
        assertTrue("Negative hex should be true", NumberUtils.isNumber("-0x123"));
    }












}

package org.apache.commons.lang3.math;

import java.io.*;
