public class NumberUtils_isNumber_TriageGen1Test {





    @Test
    public void testIsNumber_Integers() {
        assertTrue("Positive integer", NumberUtils.isNumber("123"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Negative zero", NumberUtils.isNumber("-0"));
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a plus sign", NumberUtils.isNumber("+"));
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {







    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal with digits", NumberUtils.isNumber("123.45"));
        assertTrue("Decimal with trailing dot", NumberUtils.isNumber("123."));
        assertTrue("Decimal starting with dot", NumberUtils.isNumber(".123"));
        assertTrue("Negative decimal", NumberUtils.isNumber("-123.45"));
        assertFalse("Two decimal points", NumberUtils.isNumber("12.3.4"));
        assertFalse("Dot in exponent", NumberUtils.isNumber("1e2.3"));
        assertFalse("Just a dot", NumberUtils.isNumber("."));
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {









    @Test
    public void testIsNumber_Exponents() {
        assertTrue("Scientific notation", NumberUtils.isNumber("1e10"));
        assertTrue("Scientific notation uppercase", NumberUtils.isNumber("1E10"));
        assertTrue("Scientific with sign", NumberUtils.isNumber("1e-10"));
        assertTrue("Scientific with plus sign", NumberUtils.isNumber("1e+10"));
        assertTrue("Decimal with exponent", NumberUtils.isNumber("1.23e10"));
        assertFalse("Exponent without leading digits", NumberUtils.isNumber("e10"));
        assertFalse("Two exponents", NumberUtils.isNumber("1e2e3"));
        assertFalse("Trailing exponent sign", NumberUtils.isNumber("1e+"));
        assertFalse("Trailing exponent", NumberUtils.isNumber("1e"));
        assertFalse("Exponent with dot", NumberUtils.isNumber("1e2.3"));
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue("Integer with d", NumberUtils.isNumber("123d"));
        assertTrue("Integer with D", NumberUtils.isNumber("123D"));
        assertTrue("Float with f", NumberUtils.isNumber("123f"));
        assertTrue("Float with F", NumberUtils.isNumber("123F"));

        // l, L
        assertTrue("Long with l", NumberUtils.isNumber("123l"));
        assertTrue("Long with L", NumberUtils.isNumber("123L"));

        // Restrictions on L
        assertFalse("L with exponent", NumberUtils.isNumber("1e10L"));
        assertFalse("L with decimal", NumberUtils.isNumber("1.23L"));

        // Invalid qualifiers
        assertFalse("Invalid char", NumberUtils.isNumber("123z"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {













    @Test
    public void testIsNumber_EdgeCases() {
        // testing the (i < sz + 1 && allowSigns && !foundDigit) branch
        // This targets the logic for handling signs immediately after 'e'
        assertTrue("Sign after e", NumberUtils.isNumber("1e-1"));

        // testing the logic for trailing decimal point with foundDigit
        assertTrue("Trailing dot with digit", NumberUtils.isNumber("1."));
        assertFalse("Trailing dot without digit", NumberUtils.isNumber("."));

        // testing complex combinations
        assertTrue("Negative decimal with exponent", NumberUtils.isNumber("-1.23e-4"));
        assertTrue("Decimal with F", NumberUtils.isNumber("1.23f"));

        // Testing the 'i < chars.length' block specifically
        assertFalse("Ending with E", NumberUtils.isNumber("123E"));
    }


}

